#include "varblockspmm/vbsr.hpp"
#include <algorithm>
#include <random>
#include <stdexcept>
namespace vbsr {
HostMatrix generate(const GeneratorOptions& o){ if(o.degree<1||o.degree>16||o.block_rows<1||o.block_cols<1||o.degree>o.block_cols) throw std::invalid_argument("invalid generator dimensions"); std::mt19937_64 g(o.seed); auto size=[&](){ static const int s[]={8,16,24,32,40,48,56,64}; if(o.distribution==Distribution::Uniform)return 32; if(o.distribution==Distribution::LowVariance){static const int x[]={24,32,40};return x[g()%3];} if(o.distribution==Distribution::Bimodal){static const int x[]={8,16,48,64};return x[g()%4];} return s[g()%8];}; HostMatrix a; a.block_rows=o.block_rows;a.block_cols=o.block_cols;a.row_size.resize(o.block_rows);a.col_size.resize(o.block_cols);for(auto&x:a.row_size)x=size();for(auto&x:a.col_size)x=size();a.row_scalar_off={0};for(auto x:a.row_size)a.row_scalar_off.push_back(a.row_scalar_off.back()+x);a.col_scalar_off={0};for(auto x:a.col_size)a.col_scalar_off.push_back(a.col_scalar_off.back()+x);a.row_ptr={0};a.value_off={0};std::uniform_real_distribution<float> val(-1,1);for(int i=0;i<o.block_rows;i++){std::vector<int> cols;while(int(cols.size())<o.degree){int j=o.local_columns?(i+int(g()%(2*o.degree+1))-o.degree+o.block_cols)%o.block_cols:int(g()%o.block_cols);if(std::find(cols.begin(),cols.end(),j)==cols.end())cols.push_back(j);}std::sort(cols.begin(),cols.end());for(int j:cols){a.block_col.push_back(j);int64_t count=int64_t(a.row_size[i])*a.col_size[j];for(int64_t z=0;z<count;z++)a.values.push_back(val(g));a.value_off.push_back(a.value_off.back()+count);}a.row_ptr.push_back(int(a.block_col.size()));}a.validate();return a; }
}
